import json
import os

E = "_"  # empty square marker
OUT = []


def add(p, r):
    OUT.append([p, r])


def sq(i):
    return "abcdefgh"[i % 8] + str(8 - i // 8)


def rc(i):
    return i // 8, i % 8


def idx(r, c):
    return r * 8 + c


def onb(r, c):
    return 0 <= r < 8 and 0 <= c < 8


# ---- parse input into "P:<64 squares> <castling> <ep>" ----
add(r"^(\S+) w (\S+) (\S+) \d+ \d+\s*$", r"P:\1 \2 \3")
for d in range(8, 0, -1):
    add(str(d) + r"(?=\S* )", E * d)
add(r"/(?=\S* )", "")


def board_pat(cond):
    pat = ""
    groups = []
    pos = 0
    for i in sorted(cond):
        if i > pos:
            pat += "(.{%d})" % (i - pos)
            groups.append((pos, i - pos))
        pat += "(" + cond[i] + ")"
        groups.append((i, 1))
        pos = i + 1
    if pos < 64:
        pat += "(.{%d})" % (64 - pos)
        groups.append((pos, 64 - pos))
    return pat, groups


def board_repl(groups, repl):
    out = ""
    for g, (s, l) in enumerate(groups, 1):
        if l == 1 and s in repl:
            out += repl[s]
        else:
            out += r"\g<%d>" % g
    return out, len(groups)


def gen_move(cond, repl, tag="M", castle_pat=r"(\S+)", ep_match=r"\S+", newep="-"):
    bp, groups = board_pat(cond)
    br, n = board_repl(groups, repl)
    pat = r"(?m)^P:" + bp + " " + castle_pat + " " + ep_match + "$"
    rep = r"\g<0>" + "\n" + tag + ":" + br + " " + r"\g<%d>" % (n + 1) + " " + newep
    add(pat, rep)


