gen_move(
    {60: "K", 61: E, 62: E, 63: "R"},
    {60: E, 61: "R", 62: "K", 63: E},
    tag="O",
    castle_pat=r"(\S*K\S*)",
)
gen_move(
    {56: "R", 57: E, 58: E, 59: E, 60: "K"},
    {56: E, 58: "K", 59: "R", 60: E},
    tag="o",
    castle_pat=r"(\S*Q\S*)",
