    alts = []
    for dr, dc in KN:
        if onb(r + dr, c + dc):
            alts.append(seq({idx(r + dr, c + dc): "n"}))
    for dr, dc in KG:
        if onb(r + dr, c + dc):
            alts.append(seq({idx(r + dr, c + dc): "k"}))
    for dc in (-1, 1):
        if onb(r - 1, c + dc):
            alts.append(seq({idx(r - 1, c + dc): "p"}))
    for dirs, cls in ((ORTH, "[rq]"), (DIAG, "[bq]")):
        for dr, dc in dirs:
            path = []
            rr, cc = r + dr, c + dc
            while onb(rr, cc):
                t = idx(rr, cc)
                cond = {t: cls}
                for m in path:
                    cond[m] = E
                alts.append(seq(cond))
                path.append(t)
                rr += dr
                cc += dc
    return "(?=" + "|".join(alts) + ")"


for tag, squares in (("O", (60, 61)), ("o", (60, 59))):
    for s in squares:
        add(r"(?m)^" + tag + ":" + attackers(s) + r"[^\n]*\n?", "")
add(r"(?m)^[Oo]:", "M:")
for s in range(64):
    add(r"(?m)^M:(?=.{%d}K)" % s + attackers(s) + r"[^\n]*\n?", "")

# ---- castling rights ----
for need, ch in ((60, "K"), (63, "R")):
    add(r"(?m)^(M:(?!.{%d}%s).{64} \S*?)K" % (need, ch), r"\1")
for need, ch in ((60, "K"), (56, "R")):
    add(r"(?m)^(M:(?!.{%d}%s).{64} \S*?)Q" % (need, ch), r"\1")
add(r"(?m)^(M:(?!.{7}r).{64} \S*?)k", r"\1")
add(r"(?m)^(M:(?!r).{64} \S*?)q", r"\1")
add(r"(?m)^(M:.{64})  ", r"\1 - ")

# ---- output formatting ----
add(r"(?m)^P:[^\n]*\n?", "")
add(
    r"(?m)^M:" + "(.{8})" * 8 + r" (\S+) (\S+)$",
    "/".join(r"\g<%d>" % i for i in range(1, 9)) + r" b \g<9> \g<10> 0 0",
)
for d in range(8, 0, -1):
    add(E * d, str(d))
add(r"\n+\Z", "")
add(r"\A\n+", "")

json.dump(
    OUT, open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "re.json"), "w")
)
print(len(OUT))

